{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Upcoming Gatherings</title>
  <style>
    :root{--bg:#0f1720;--card:rgba(255,255,255,0.06);--glass:rgba(255,255,255,0.08);--accent:#8bd3c7;--muted:#aab3bf;--glass-2:rgba(255,255,255,0.03)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6eef0;background:linear-gradient(180deg,#06111a 0%, #071622 100%);} 
    .wrap{max-width:1100px;margin:36px auto;padding:36px;position:relative}
    header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:28px}
    .brand{display:flex;align-items:center;gap:14px}
    .logo{width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#6ea6ff);box-shadow:0 6px 24px rgba(14,20,25,0.6)}
    nav a{color:#cfe9e3;text-decoration:none;margin:0 10px;font-size:14px}
    .hero{background:linear-gradient(135deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));backdrop-filter:blur(8px);border-radius:14px;padding:28px;display:flex;gap:24px;align-items:center}
    .hero .left{flex:1}
    h1{margin:0 0 6px 0;font-weight:600;font-size:24px;color:#e9fbf6}
    p.lead{margin:0;color:var(--muted)}
    .cta{margin-top:14px}
    .btn{background:var(--accent);color:#022; padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:600}

    /* glass cards */
    .grid{display:grid;grid-template-columns:1fr 340px;gap:20px;margin-top:24px}
    .card{background:var(--card);border-radius:12px;padding:16px;box-shadow:inset 0 1px 0 rgba(255,255,255,0.02)}

    /* Next event */
    .next{display:flex;flex-direction:column;gap:8px}
    .badge{display:inline-block;padding:6px 10px;border-radius:999px;background:rgba(139,211,199,0.12);color:var(--accent);font-weight:600}
    .meta{color:var(--muted);font-size:14px}

    /* calendar list */
    .events-list{margin-top:10px;display:flex;flex-direction:column;gap:8px}
    .event-item{display:flex;justify-content:space-between;align-items:center;padding:10px;border-radius:10px;background:var(--glass-2)}
    .event-date{font-weight:700;color:#dff7f1}
    .event-info{color:var(--muted);font-size:13px}

    /* Proof gallery */
    .proof{margin-top:20px}
    .testimonial{padding:14px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);min-height:104px;display:flex;flex-direction:column;justify-content:center;transition:opacity .6s,transform .6s}
    .testimonial p{margin:0;color:#eaf8f4}
    .t-author{margin-top:10px;color:var(--muted);font-size:13px}
    .badges{display:flex;gap:8px;margin-top:12px}
    .badge-chip{background:rgba(255,255,255,0.03);padding:6px 8px;border-radius:8px;font-size:13px;color:var(--muted);position:relative}
    .tooltip{position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);background:#042024;color:#bff1e5;padding:8px;border-radius:6px;font-size:12px;white-space:nowrap;display:none}
    .badge-chip:hover .tooltip{display:block}

    /* small print */
    .small{font-size:12px;color:var(--muted);margin-top:12px}

    footer{margin-top:28px;color:var(--muted);font-size:13px;text-align:center}

    /* responsive */
    @media(max-width:840px){.grid{grid-template-columns:1fr}.wrap{padding:18px}}

    /* decorative SVG pattern */
    .pattern{position:absolute;right:-60px;top:-60px;opacity:0.12;width:420px;height:420px;background-image:url('assets/img/pattern.svg');background-size:cover;filter:blur(1px)}
  </style>
</head>
<body>
  <div class="wrap">
    <div class="pattern" aria-hidden="true"></div>
    <header>
      <div class="brand">
        <div class="logo" aria-hidden="true"></div>
        <div>
          <div style="font-weight:700;color:#e8fbf6">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted);margin-top:2px">A place to reshape hush into clarity</div>
        </div>
      </div>
      <nav aria-label="Main navigation">
        <a href="index.html">Home</a>
        <a href="events.html">Gatherings</a>
        <a href="private-sessions.html">Solo Sessions</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">Story</a>
        <a href="faq.html">Help</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Reach</a>
      </nav>
    </header>

    <section class="hero card">
      <div class="left">
        <h1>Evening sound gatherings — tuned for welcome</h1>
        <p class="lead">A measured hour of layered tones to unwind attention and steady the pace of the day. Gentle, grounded, and suitable for many bodies.</p>
        <div class="cta"><a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
      </div>
      <div style="width:300px;text-align:right;color:var(--muted)">
        <div class="badge">Next — Fri</div>
        <div style="font-weight:700;font-size:18px;color:#eafbf7;margin-top:8px">Full-sound evening</div>
        <div class="meta">7:00 PM • {{CITY}}, {{STATE}}</div>
      </div>
    </section>

    <div class="grid">
      <main>
        <div class="card">
          <div class="next">
            <div class="badge">Upcoming session</div>
            <div style="display:flex;justify-content:space-between;align-items:center">
              <div>
                <div style="font-weight:700;color:#eafbf7">Small-room sound bath</div>
                <div class="meta">Saturday • Feb 28 • 5:30 PM</div>
                <div class="small">Capacity limited — mats provided on request</div>
              </div>
              <div style="text-align:right">
                <div style="font-weight:800;color:#dff7f1">$28</div>
                <a class="btn" href="book.html" style="display:inline-block;margin-top:8px">Reserve a spot</a>
              </div>
            </div>
          </div>

          <div style="margin-top:14px">
            <h3 style="margin:0 0 8px 0;color:#eafbf7">Calendar</h3>
            <div class="events-list" id="calendar">
              <!-- JS fills this -->
            </div>
          </div>

          <div class="small" style="margin-top:12px">If you have pacemakers, recent surgeries, seizures, or are pregnant, please consult your physician before booking. Contact <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> for guidance.</div>
        </div>

        <div class="proof card" aria-live="polite">
          <h3 style="margin:0 0 8px 0;color:#eafbf7">Community notes</h3>
          <div id="testimonial" class="testimonial" data-index="0">
            <p id="t-text">"The room opened a quiet place in my breathing — a small, steady relief."</p>
            <div class="t-author" id="t-author">— A. (attendee)</div>
            <div class="badges" id="cred">
              <div class="badge-chip">Featured in: Quiet City Magazine<div class="tooltip">Profiled for best local restorative events</div></div>
              <div class="badge-chip">Verified host<div class="tooltip">Background checks and safety protocols in place</div></div>
              <div class="badge-chip">Community rated<div class="tooltip">4.8 / 5 from repeat attendees</div></div>
            </div>
          </div>
        </div>
      </main>

      <aside>
        <div class="card">
          <h4 style="margin:0 0 8px 0;color:#eafbf7">What to bring</h4>
          <ul style="margin:0;padding-left:18px;color:var(--muted)">
            <li>Comfortable layers</li>
            <li>Optional eye-cover and small pillow</li>
            <li>Open curiosity, not performance</li>
          </ul>

          <div style="margin-top:12px">
            <h4 style="margin:0 0 6px 0;color:#eafbf7">Access</h4>
            <div class="meta">Wheelchair accessible entrance. Small steps inside; let us know.</div>
          </div>

          <div style="margin-top:14px;text-align:center">
            <a class="btn" href="book.html">Hold a mat</a>
            <div class="small">or call <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <h4 style="margin:0 0 8px 0;color:#eafbf7">Notes on suitability</h4>
          <div class="small">Sound work is supportive for many, but not all. Please reach out before booking if you have epilepsy, significant hearing conditions, or medical devices. We can adapt where possible.</div>
        </div>
      </aside>
    </div>

    <footer>
      <div class="small">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
    </footer>
  </div>

  <script>
    // Calendar list + next-event logic
    const events = [
      {date:'2026-02-28',label:'Small-room sound bath',time:'5:30 PM',price:28},
      {date:'2026-03-05',label:'Evening full resonance',time:'7:00 PM',price:35},
      {date:'2026-03-12',label:'Weekend slow sound',time:'4:00 PM',price:30},
      {date:'2026-03-19',label:'Community practice circle',time:'6:30 PM',price:20}
    ];

    function renderCalendar(){
      const el = document.getElementById('calendar');
      el.innerHTML='';
      events.forEach(ev=>{
        const item = document.createElement('div');
        item.className='event-item';
        item.innerHTML = '<div><div class="event-date">'+new Date(ev.date).toLocaleDateString()+ ' · '+ev.time+'</div><div class="event-info">'+ev.label+'</div></div><div style="text-align:right"><div style="font-weight:700;color:#dff7f1">$'+ev.price+'</div><a href="book.html" style="color:var(--accent);font-size:13px;text-decoration:none">Reserve</a></div>';
        el.appendChild(item);
      });
    }

    // Proof gallery rotator
    const testimonials = [
      {text:'A steady palette of tones that made my shoulders soften. I slept more soundly that night.',author:'M.'},
      {text:'Not loud, not showy — kind and precise. The leader kept everything gentle but intentional.',author:'R.'},
      {text:'I went for curiosity and left with a clearer neck and calmer head.',author:'S.'}
    ];
    let tIndex=0;
    const tText = document.getElementById('t-text');
    const tAuthor = document.getElementById('t-author');
    function showTest(i){
      const t = testimonials[i%testimonials.length];
      tText.style.opacity=0; tAuthor.style.opacity=0;
      setTimeout(()=>{ tText.textContent='"'+t.text+'"'; tAuthor.textContent='— '+t.author; tText.style.opacity=1; tAuthor.style.opacity=1 },300);
    }
    showTest(0);
    setInterval(()=>{ tIndex=(tIndex+1)%testimonials.length; showTest(tIndex); },5000);

    renderCalendar();
  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Solo Sessions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#07131a;--card:rgba(255,255,255,0.04);--accent:#9be3d0;--muted:#9fb0ba}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#031017 0%,#07131a 100%);color:#e9fbf6}
    .container{max-width:980px;margin:36px auto;padding:32px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:#bfeee5;margin:0 10px;text-decoration:none;font-size:13px}
    .glass{background:var(--card);padding:18px;border-radius:12px;backdrop-filter:blur(8px);}
    h1{margin:0 0 6px 0}
    .intro{color:var(--muted);margin-bottom:14px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}

    /* session cards */
    .session{padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);margin-bottom:12px}
    .price{font-weight:800;color:#dffbf7}

    /* comparator */
    .compare{display:flex;align-items:center;gap:12px;margin-top:10px}
    .toggle{background:rgba(255,255,255,0.02);padding:6px;border-radius:999px;display:flex}
    .toggle button{background:transparent;border:0;padding:8px 12px;color:var(--muted);cursor:pointer;border-radius:999px}
    .toggle button.active{background:var(--accent);color:#042023}
    .figure{font-size:32px;font-weight:800;color:#e9fbf6}

    .note{font-size:13px;color:var(--muted);margin-top:10px}

    .proof{margin-top:14px}
    .testimonial{padding:12px;border-radius:10px;background:rgba(255,255,255,0.02)}

    footer{margin-top:18px;color:var(--muted);font-size:13px;text-align:center}
  </style>
</head>
<body>
  <div class="container">
    <header>
      <div>
        <div style="font-weight:700;font-size:18px">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Tailored one-on-one sound guidance</div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="events.html">Gatherings</a>
        <a href="private-sessions.html">Solo Sessions</a>
        <a href="pricing.html">Investment</a>
      </nav>
    </header>

    <main style="margin-top:18px">
      <div class="glass">
        <h1>Private sessions</h1>
        <div class="intro">One guest at a time. We shape a session to the pace you need — restorative, focused, or integrative.</div>

        <div class="grid">
          <section>
            <div class="session">
              <div style="display:flex;justify-content:space-between;align-items:center">
                <div>
                  <div style="font-weight:700">Short session</div>
                  <div class="note">30 minutes — focused relief</div>
                </div>
                <div class="price">$70</div>
              </div>
            </div>

            <div class="session">
              <div style="display:flex;justify-content:space-between;align-items:center">
                <div>
                  <div style="font-weight:700">Standard session</div>
                  <div class="note">60 minutes — full recalibration</div>
                </div>
                <div class="price">$120</div>
              </div>
            </div>

            <div class="session">
              <div style="display:flex;justify-content:space-between;align-items:center">
                <div>
                  <div style="font-weight:700">Deep hour</div>
                  <div class="note">90 minutes — extended restorative work</div>
                </div>
                <div class="price">$170</div>
              </div>
            </div>

            <div style="margin-top:10px">
              <div style="font-weight:600">Compare plans</div>
              <div class="compare">
                <div class="toggle" role="tablist" aria-label="Pricing toggle">
                  <button id="t-month" class="active">Per session</button>
                  <button id="t-package">3-session package</button>
                </div>
                <div style="margin-left:auto;text-align:right">
                  <div class="figure" id="price-figure">$120</div>
                  <div class="note" id="price-note">Standard</div>
                </div>
              </div>
            </div>

            <div class="note">Packages may include priority booking. Please ask about accessibility and comfort adaptations prior to booking.</div>

            <div style="margin-top:14px">
              <a class="btn" href="book.html" style="background:var(--accent);color:#042021;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700">Arrange a session</a>
            </div>

            <div class="proof" aria-live="polite">
              <h3 style="margin-top:14px;margin-bottom:8px">What clients say</h3>
              <div id="test-ps" class="testimonial">"Attentive, calm, and deeply held — I left with clear shoulders." — J.</div>
            </div>

            <div class="note" style="margin-top:12px">Contraindications: If you are pregnant, have an implanted medical device, epilepsy, or other significant medical conditions, consult your clinician before booking. Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> for adaptations.</div>
          </section>

          <aside class="glass" style="padding:16px">
            <h4 style="margin-top:0">Process</h4>
            <div style="font-size:13px;color:var(--muted)">
              1) Pre-chat to understand needs. 2) Gentle session with layered tones. 3) Debrief and practices to carry forward.
            </div>

            <div style="margin-top:12px">
              <div style="font-weight:700">Why choose solo work?</div>
              <div class="note">More room for intention and specific physical support. We slow the frame to fit you.</div>
            </div>

            <div style="margin-top:14px">
              <a href="contact.html" style="color:var(--accent);text-decoration:none;font-weight:700">Ask about your needs</a>
            </div>
          </aside>
        </div>
      </div>
    </main>

    <footer>
      <div class="note">Need a custom plan? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </footer>
  </div>

  <script>
    // Pricing comparator with animated numbers
    const monthlyBtn = document.getElementById('t-month');
    const packageBtn = document.getElementById('t-package');
    const figure = document.getElementById('price-figure');
    const note = document.getElementById('price-note');

    const plans = {
      standard: {per:120,pack:320}, // pack price total for 3 sessions
      short: {per:70,pack:180},
      deep: {per:170,pack:450}
    };

    let activePlan='standard';
    let mode='per';

    function animateValue(el, start, end, duration){
      const startTime = performance.now();
      function step(now){
        const progress = Math.min((now-startTime)/duration,1);
        const value = Math.round(start + (end-start)*progress);
        el.textContent = '$'+value;
        if(progress<1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }

    function updateDisplay(){
      const target = plans[activePlan][mode];
      animateValue(figure, parseInt(figure.textContent.replace('$',''))||0, target, 500);
      note.textContent = mode==='per' ? 'Standard' : '3-session package';
    }

    monthlyBtn.addEventListener('click',()=>{mode='per'; monthlyBtn.classList.add('active'); packageBtn.classList.remove('active'); updateDisplay();});
    packageBtn.addEventListener('click',()=>{mode='pack'; packageBtn.classList.add('active'); monthlyBtn.classList.remove('active'); updateDisplay();});

    // initialize
    figure.textContent='$120';
    note.textContent='Standard';
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — Offerings & Packages</title>
  <style>
    :root{--bg:#06121a;--card:rgba(255,255,255,0.035);--accent:#7fe1c3;--muted:#a9bcc2}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#031014, #06121a);color:#eafef8}
    .center{max-width:1000px;margin:36px auto;padding:28px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:#bfece5;margin:0 10px;text-decoration:none}
    .hero{background:var(--card);padding:18px;border-radius:12px;margin-top:18px}
    .plans{display:flex;gap:14px;margin-top:18px}
    .plan{flex:1;padding:14px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .title{font-weight:700}
    .price{font-size:28px;font-weight:800;color:#e8fff9}

    .comparator{display:flex;align-items:center;gap:12px;margin-top:12px}
    .switch{background:rgba(255,255,255,0.02);padding:6px;border-radius:999px}
    .switch button{background:transparent;border:0;padding:8px 12px;color:var(--muted);cursor:pointer;border-radius:999px}
    .switch button.active{background:var(--accent);color:#022}

    .feature-list{margin-top:10px;color:var(--muted);font-size:14px}
    .cta{margin-top:16px}
    .disclaimer{font-size:13px;color:var(--muted);margin-top:12px}

    .pattern{position:absolute;left:-40px;bottom:-60px;opacity:0.08;width:420px;height:420px;background-image:url('assets/img/pattern.svg');background-size:cover}

    @media(max-width:900px){.plans{flex-direction:column}}
  </style>
</head>
<body>
  <div class="center">
    <div class="pattern" aria-hidden="true"></div>
    <header>
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Home</a>
        <a href="events.html">Gatherings</a>
        <a href="private-sessions.html">Solo Sessions</a>
        <a href="pricing.html">Investment</a>
      </nav>
    </header>

    <section class="hero">
      <h1 style="margin:0">Offerings & packages</h1>
      <div style="color:var(--muted);margin-top:6px">Transparent rates and short package options for repeat practice.</div>

      <div class="comparator" style="margin-top:12px">
        <div style="font-weight:700">Show:</div>
        <div class="switch" role="tablist">
          <button id="s-per" class="active">Per session</button>
          <button id="s-package">Package</button>
        </div>
        <div style="margin-left:auto;color:var(--muted);font-size:14px">Toggle to compare solo session prices and bundle savings</div>
      </div>
    </section>

    <div class="plans">
      <div class="plan">
        <div class="title">Short session</div>
        <div class="price" data-per="70" data-pack="180" id="p1">$70</div>
        <div class="feature-list">
          <div>- 30 minutes</div>
          <div>- Focused relief</div>
          <div>- Great as a reset between busy days</div>
        </div>
        <div class="cta"><a href="book.html" style="background:var(--accent);color:#022;padding:10px 12px;border-radius:10px;text-decoration:none;font-weight:700">Book short</a></div>
      </div>

      <div class="plan">
        <div class="title">Standard session</div>
        <div class="price" data-per="120" data-pack="320" id="p2">$120</div>
        <div class="feature-list">
          <div>- 60 minutes</div>
          <div>- Guided, full recalibration</div>
          <div>- Best-seller for first-time guests</div>
        </div>
        <div class="cta"><a href="book.html" style="background:var(--accent);color:#022;padding:10px 12px;border-radius:10px;text-decoration:none;font-weight:700">Book standard</a></div>
      </div>

      <div class="plan">
        <div class="title">Deep hour</div>
        <div class="price" data-per="170" data-pack="450" id="p3">$170</div>
        <div class="feature-list">
          <div>- 90 minutes</div>
          <div>- Extended, immersive work</div>
          <div>- For layered restoration</div>
        </div>
        <div class="cta"><a href="book.html" style="background:var(--accent);color:#022;padding:10px 12px;border-radius:10px;text-decoration:none;font-weight:700">Book deep</a></div>
      </div>
    </div>

    <div class="glass" style="margin-top:18px;padding:14px;border-radius:12px;background:rgba(255,255,255,0.02)">
      <div style="display:flex;gap:12px;align-items:center">
        <div style="font-weight:700">Savings note</div>
        <div style="color:var(--muted)">Packages show the total for three sessions; billed up front. Savings reflect reduced per-session cost.</div>
      </div>

