    <footer style="margin-top:18px;color:var(--muted)">Need a tailored plan? <a href="contact.html" style="color:var(--accent);text-decoration:none">Get in touch</a> • or call <a href="tel:{{PHONE}}" style="color:var(--accent);text-decoration:none">{{PHONE}}</a></footer>
  </div>

  <script>
    // Pricing comparator: animate numbers for all three plans
    const perBtn = document.getElementById('s-per');
    const packBtn = document.getElementById('s-package');
    const prices = [document.getElementById('p1'),document.getElementById('p2'),document.getElementById('p3')];

    function animate(el,from,to){
      const start = performance.now();
      const dur = 450;
      function step(now){
        const t = Math.min((now-start)/dur,1);
        const val = Math.round(from + (to-from)*t);
        el.textContent = '$'+val;
        if(t<1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }

    function showMode(mode){
      prices.forEach(p=>{
        const per = parseInt(p.getAttribute('data-per'));
        const pack = parseInt(p.getAttribute('data-pack'));
        const from = parseInt(p.textContent.replace('$',''))||per;
        const to = mode==='per' ? per : pack;
        animate(p,from,to);
      });
    }

    perBtn.addEventListener('click',()=>{perBtn.classList.add('active');packBtn.classList.remove('active');showMode('per')});
    packBtn.addEventListener('click',()=>{packBtn.classList.add('active');perBtn.classList.remove('active');showMode('pack')});
  </script>
